def escape(with_fire):
    fire = {(1, 2)} if with_fire else set(); me = {(3, 3)}; t = 0
    while me:
        if any(r in (0, 6) or c in (0, 6) for r, c in me): return t
        t += 1
        me = ({(r + dr, c + dc) for r, c in me for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))} & free) - fire
        if with_fire: fire = fire | ({(r + dr, c + dc) for r, c in fire for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))} & free)
        me -= fire
    return -1
